def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
    opp_d = n - opp_c

    r5_c = 0
    for _, o in history[-5:]:
        if o == 'C':
            r5_c += 1

    r10_c = 0
    for _, o in history[-10:]:
        if o == 'C':
            r10_c += 1

    cd = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'D':
            cd += 1
        else:
            break

    dd = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            dd += 1
        else:
            break

    if n == 98:
        if last_opp == 'C' and r10_c >= 6 and opp_c * 2 >= n:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            if cd >= 2:
                return 'D'
            if r5_c >= 1:
                return 'C'
            if opp_d * 4 <= n:
                return 'C'
            if n <= 6 and opp_d <= 1:
                return 'C'
            return 'D'

        if opp_c * 3 >= n * 2 and dd >= 2:
            return 'C'
        if r5_c >= 3 and dd >= 3:
            return 'C'
        if dd >= 5 and rng.random() < 0.05:
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'
    return 'C'
